results.js:
morse.every(100, () => {
  const doc = document.documentElement;
  const max = doc.scrollHeight - doc.clientHeight;
  const pct = max > 0 ? Math.min(100, (doc.scrollTop / max) * 100) : 0;
  document.body.style.setProperty("--read-progress", pct + "%");
});

