results.js:
morse.watch("body > div.mn > h1", h1 => {
  if (h1.dataset.csvAdded) return;
  h1.dataset.csvAdded = "1";
  h1.style.display = "flex";
  h1.style.alignItems = "center";
  const btn = morse.el("button", {
    id: "morse-csv-btn",
    text: "Export CSV",
    on: {
      click: () => {
        const rows = morse.$$("body > div.mn > div.row2 > div.tbl table tr");
        const csv = rows.map(tr =>
          Array.from(tr.children).map(c => {
            const t = c.textContent.trim().replace(/"/g, '""');
            return `"${t}"`;
          }).join(",")
        ).join("\n");
        const a = morse.el("a", {
          href: "data:text/csv;charset=utf-8," + encodeURIComponent(csv),
          download: "orders.csv"
        });
        document.body.appendChild(a);
        a.click();
        a.remove();
        morse.toast("Exported " + Math.max(rows.length - 1, 0) + " orders");
      }
    }
  });
  h1.appendChild(btn);
});

morse.watch("td.am", el => {
  const n = parseFloat(el.textContent.replace(/[^0-9.\-]/g, ""));
  if (isNaN(n)) return;
  el.textContent = "$" + n.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
});

morse.watch("div.tbl table", table => {
  const th = table.querySelector("th.am");
  if (!th || th.dataset.sortBound) return;
  th.dataset.sortBound = "1";
  th.style.cursor = "pointer";
  th.title = "Click to sort by amount";
  let asc = false;
  th.addEventListener("click", () => {
    const tbody = table.querySelector("tbody");
    const rows = Array.from(tbody.querySelectorAll("tr"));
    rows.sort((a, b) => {
      const x = parseFloat(a.querySelector("td.am")?.textContent.replace(/[^0-9.\-]/g, "")) || 0;
      const y = parseFloat(b.querySelector("td.am")?.textContent.replace(/[^0-9.\-]/g, "")) || 0;
      return asc ? x - y : y - x;
    });
    rows.forEach(r => tbody.appendChild(r));
    asc = !asc;
    th.textContent = "Amount " + (asc ? "▲" : "▼");
  });
});

