results.js:
const fmt = n => n.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const total = () => morse.$$("div.tbl tbody td.am").reduce((s, td) => s + (parseFloat(td.textContent) || 0), 0);

morse.watch("div.tbl table", table => {
  const cell = morse.el("td", { class: "am", text: fmt(total()) });
  table.appendChild(
    morse.el("tfoot", { class: "mod-total" },
      morse.el("tr", {},
        morse.el("td", { colspan: "4", text: "Total" }),
        cell
      )
    )
  );
});

morse.every(500, () => {
  const cell = morse.$(".mod-total td.am");
  const t = fmt(total());
  if (cell && cell.textContent !== t) cell.textContent = t;
});

morse.every(1000, () => {
  const unread = morse.$$('[role="option"][data-unread="true"]').length;
  const base = document.title.replace(/^\(\d+\)\s*/, "");
  document.title = unread ? `(${unread}) ${base}` : base;
});

