morse.on(document, "keydown", e => {
  if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "s") {
    e.preventDefault();
    morse.toast("Saved");
  }
});

morse.watch('div[aria-label="Formatting"]', bar => {
  if (bar.querySelector('button.today-date')) return;
  const btn = morse.el('button', {
    class: 'today-date',
    title: "Insert today's date",
    text: 'Date',
    on: {
      click: () => {
        const d = new Date();
        const label = d.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
        const ed = morse.$('div[role="textbox"]');
        if (!ed) return morse.toast('No editor found');
        ed.focus();
        const sel = window.getSelection();
        if (sel && sel.rangeCount && ed.contains(sel.anchorNode)) {
          const range = sel.getRangeAt(0);
          range.deleteContents();
          range.insertNode(document.createTextNode(label));
          range.collapse(false);
        } else {
          ed.appendChild(document.createTextNode(label));
        }
        ed.dispatchEvent(new Event('input', { bubbles: true }));
      }
    }
  });
  bar.appendChild(btn);
});

