results.js:
morse.watch(".ed_9f", el => {
  let badge = el.parentElement.querySelector(".morse-wc");
  if (!badge) {
    badge = morse.el("div", {
      class: "morse-wc",
      style: "font-size:12px;color:rgb(155,154,151);margin-top:8px;"
    });
    el.insertAdjacentElement("afterend", badge);
  }
  const update = () => {
    const text = (el.innerText || "").trim();
    const words = text ? text.split(/\s+/).length : 0;
    badge.textContent = words + (words === 1 ? " word" : " words");
  };
  update();
  morse.on(el, "input", update);
});

