results.js:
morse.watch('header[role="banner"] > div:last-of-type', el => {
  if (el.querySelector(".morse-copy-md")) return;
  const btn = morse.el("button", {
    class: "morse-copy-md",
    text: "Copy as Markdown",
    on: {
      click: async () => {
        const msgs = morse.$$('section[aria-label="Conversation"] .msg');
        if (!msgs.length) { morse.toast("No messages to copy"); return; }
        const md = msgs.map(m => {
          const who = m.dataset.role === "user" ? "You" : "Parley";
          return `**${who}:** ${m.textContent.trim()}`;
        }).join("\n\n");
        try {
          await navigator.clipboard.writeText(md);
          morse.toast("Conversation copied as Markdown");
        } catch (e) {
          morse.toast("Couldn't copy to clipboard");
        }
      }
    }
  });
  el.insertBefore(btn, el.firstChild);
});

morse.watch('textarea[aria-label="Message Parley"]', el => {
  if (el._escClear) return;
  el._escClear = true;
  morse.on(el, 'keydown', e => {
    if (e.key === 'Escape' && el.value !== '') {
      el.value = '';
      el.dispatchEvent(new Event('input', { bubbles: true }));
      e.stopPropagation();
    }
  });
});

