results.js:
morse.watch("textarea[aria-label=\"Message\\ Parley\"]", ta => {
  const holder = ta.closest("#composer > div");
  const update = () => {
    const n = ta.value.trim() ? ta.value.trim().split(/\s+/).length : 0;
    holder.dataset.words = n + (n === 1 ? " word" : "") ;
    holder.dataset.words = n;
  };
  morse.on(ta, "input", update);
  update();
});

