results.js:
morse.watch('div[data-testid="player-controls"] .btns', function (row) {
  if (row.querySelector('[data-sleep]')) return;
  var steps = [0, 15, 30, 60];
  var i = 0;
  var timer = null;
  var btn = morse.el('button', {
    'data-sleep': '',
    'aria-label': 'Sleep timer',
    title: 'Sleep timer',
    text: '☾'
  });
  morse.on(btn, 'click', function () {
    i = (i + 1) % steps.length;
    var m = steps[i];
    clearTimeout(timer);
    timer = null;
    if (m === 0) {
      btn.textContent = '☾';
      morse.toast('Sleep timer off');
      return;
    }
    timer = setTimeout(function () {
      var p = document.querySelector('[data-testid="play-pause"]');
      if (p && p.getAttribute('aria-label') === 'Pause') p.click();
      btn.textContent = '☾';
    }, m * 60000);
    btn.textContent = m + 'm';
    morse.toast('Pausing in ' + m + ' minutes');
  });
  row.appendChild(btn);
});
